import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import axios from 'axios';
import toast from 'react-hot-toast';

const Dashboard = () => {
  const { user } = useAuth();
  const navigate = useNavigate();
  const [stats, setStats] = useState({ totalProblems: 0 });

  useEffect(() => {
    fetchStats();
  }, []);

  const fetchStats = async () => {
    try {
      const token = localStorage.getItem('token');
      const response = await axios.get('http://localhost:5000/api/problems', {
        headers: { Authorization: `Bearer ${token}` }
      });
      setStats({ totalProblems: response.data.problems?.length || 0 });
    } catch (error) {
      console.error('Error fetching stats:', error);
    }
  };

  const statCards = [
    { icon: '✅', label: 'Problems Solved', value: user?.stats?.problemsSolved || 0, color: '#4CAF50' },
    { icon: '📝', label: 'Total Attempts', value: user?.stats?.totalAttempts || 0, color: '#2196F3' },
    { icon: '📚', label: 'Total Problems', value: stats.totalProblems, color: '#FF9800' },
    { icon: '🏆', label: 'Success Rate', value: user?.stats?.totalAttempts > 0 
        ? Math.round((user.stats.problemsSolved / user.stats.totalAttempts) * 100) 
        : 0, color: '#9C27B0', suffix: '%' },
  ];

  const quickActions = [
    { icon: '📚', label: 'Browse Problems', path: '/problems' },
    { icon: '📊', label: 'View Submissions', path: '/submissions' },
  ];

  if (user?.role === 'admin' || user?.role === 'setter') {
    quickActions.push({ icon: '➕', label: 'Create Problem', path: '/create-problem' });
  }

  return (
    <div style={{
      minHeight: '100vh',
      padding: '30px',
      background: '#f0f2f5',
    }}>
      {/* Welcome Section */}
      <div style={{
        background: 'linear-gradient(135deg, #667eea, #764ba2)',
        borderRadius: '20px',
        padding: '40px',
        marginBottom: '30px',
        color: 'white',
        position: 'relative',
        overflow: 'hidden',
      }}>
        <div style={{ position: 'relative', zIndex: 2 }}>
          <h1 style={{ fontSize: '32px', fontWeight: 700 }}>
            Welcome back, {user?.username}! 👋
          </h1>
          <p style={{ opacity: 0.9, marginTop: '8px', fontSize: '16px' }}>
            {user?.role === 'admin' ? '🔑 Admin' : 
             user?.role === 'setter' ? '✍️ Problem Setter' : '🎓 Student'}
          </p>
          <div style={{ marginTop: '15px' }}>
            <span style={{
              background: 'rgba(255,255,255,0.2)',
              padding: '6px 16px',
              borderRadius: '20px',
              fontSize: '13px',
            }}>
              {user?.stats?.problemsSolved || 0} problems solved
            </span>
          </div>
        </div>
        <div style={{
          position: 'absolute',
          right: '-50px',
          top: '-50px',
          fontSize: '200px',
          opacity: 0.1,
        }}>
          ⚡
        </div>
      </div>

      {/* Stats Grid */}
      <div style={{
        display: 'grid',
        gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))',
        gap: '20px',
        marginBottom: '30px',
      }}>
        {statCards.map((stat, index) => (
          <div
            key={index}
            style={{
              background: 'white',
              padding: '24px',
              borderRadius: '16px',
              boxShadow: '0 4px 20px rgba(0,0,0,0.06)',
            }}
          >
            <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
              <span style={{ fontSize: '28px' }}>{stat.icon}</span>
              <div>
                <p style={{ fontSize: '13px', color: '#666' }}>{stat.label}</p>
                <p style={{ fontSize: '28px', fontWeight: 700, color: stat.color }}>
                  {stat.value}{stat.suffix || ''}
                </p>
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* Quick Actions */}
      <div style={{
        background: 'white',
        padding: '24px',
        borderRadius: '16px',
        boxShadow: '0 4px 20px rgba(0,0,0,0.06)',
      }}>
        <h3 style={{ marginBottom: '15px', fontSize: '18px' }}>🚀 Quick Actions</h3>
        <div style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fit, minmax(150px, 1fr))',
          gap: '15px',
        }}>
          {quickActions.map((action, index) => (
            <div
              key={index}
              onClick={() => navigate(action.path)}
              style={{
                padding: '20px',
                background: '#f8f9fa',
                borderRadius: '12px',
                textAlign: 'center',
                cursor: 'pointer',
                transition: 'all 0.3s',
              }}
              onMouseEnter={(e) => e.currentTarget.style.transform = 'scale(1.05)'}
              onMouseLeave={(e) => e.currentTarget.style.transform = 'scale(1)'}
            >
              <div style={{ fontSize: '32px', marginBottom: '8px' }}>{action.icon}</div>
              <p style={{ fontSize: '14px', fontWeight: 500 }}>{action.label}</p>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
